function validate([target]) {
  if (typeof target !== 'string' || target.length < 1 || target.length > 400) return 'target has 1 to 400 letters.';
  if (!/^[a-z]+$/.test(target)) return 'target uses only lowercase English letters.';
  // The answer's JSON text: letter i shows up to 26 screens of i + 1 letters, each with 2 quotes and a separator.
  let output = 1;
  for (let i = 0; i < target.length; i++) output += (target.charCodeAt(i) - 96) * (i + 4);
  if (output > 262144) return 'The answer for this target is too large for the local judge (over 256 KiB); try a shorter target or earlier letters.';
  return null;
}

