function stringSequence(target) {
  const screens = [];
  let typed = '';
  for (const letter of target) {
    let last = 'a';
    screens.push(typed + last);
    while (last !== letter) {
      last = String.fromCharCode(last.charCodeAt(0) + 1);
      screens.push(typed + last);
    }
    typed += letter;
  }
  return screens;
}

