function stringSequence(target) {
  // Breadth-first search over screens, one key press per edge, which finds a shortest typing directly.
  // A screen is kept only if every letter but its last already matches target: those letters can no longer change.
  const parent = new Map([['', null]]);
  const queue = [''];
  for (let head = 0; head < queue.length && !parent.has(target); head++) {
    const screen = queue[head];
    const options = [screen + 'a'];
    if (screen.length > 0) {
      const shifted = (screen.charCodeAt(screen.length - 1) - 97 + 1) % 26;
      options.push(screen.slice(0, -1) + 'abcdefghijklmnopqrstuvwxyz'[shifted]);
    }
    for (const next of options) {
      if (next.length > target.length || parent.has(next)) continue;
      if (next.slice(0, -1) !== target.slice(0, next.length - 1)) continue;
      parent.set(next, screen);
      queue.push(next);
    }
  }
  const path = [];
  for (let screen = target; screen !== ''; screen = parent.get(screen)) path.push(screen);
  return path.reverse();
}

