function generate(rand, size) {
  // Large targets are 400 early letters, or random letters until the answer nears the 256 KiB output limit.
  const length = size === 'large' ? 400 : 1 + Math.floor(rand() * 5);
  const span = size === 'large' && rand() < 0.5 ? 4 : 26;
  let target = '';
  let output = 1;
  while (target.length < length) {
    const roll = rand();
    // Small inputs lean on the edge letters a and z.
    const code = size === 'small' && roll < 0.2 ? 0 : size === 'small' && roll < 0.4 ? 25 : Math.floor(rand() * span);
    output += (code + 1) * (target.length + 4);
    if (output > 250000) break;
    target += String.fromCharCode(97 + code);
  }
  return [target];
}
